    _DEVICE_LOADING_TIME = 2
    _OPERATION_DELAY_TIME = _DEVICE_LOADING_TIME / 10.0
    _LOCK_FILE_NAME = u'lock.file'

    def __init__(self, ip, port=5025, unlock_timeout=300):
        """
        Initiates instance of handler for Keysight signal analyzer and
        locks device until handler instance is no longer in use.
        If device is locked by other user, then locking is retired until success or reaching timeout.
        :param ip: IP address of signal analyzer to which connection will be established
        :type ip: str
        :param port: port number which allows connection to signal analyzer; defaults to 5025
        :type port: int
        :param unlock_timeout: time to wait for device do became unlocked by other possible user;
                               defaults to 300 seconds
        :type unlock_timeout: int
        :raises DeviceLocked: when device doesn't became unlocked by other user before reaching timeout
        """
        super(Keysight, self).__init__()
        self._transport = ScpiClient(ip=ip, port=int(port))
        self._lock_device(int(unlock_timeout))
        self._mode = self.get_mode()

    def __del__(self):
        """
        Unlocks device upon deletion of handler instance.
        :raises CannotUnlockDevice: when device is still locked after attempt to unlock it
        """
        self._unlock_device()

    def set_mode(self, mode, timeout=20):
        """
        Sets given operating mode on the device.
        :param mode: one of available modes: SA, RTSA
        :type mode: str
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 20 seconds
        :type timeout: int
        :raises IncorrectOperation: when unsupported mode is provided
        """
        self._check_mode(mode)
        command = self._SET_MODE_CMD.format(mode)
        self._execute_command(command, timeout, self._DEVICE_LOADING_TIME)
        self._mode = self.get_mode()

    def get_mode(self, timeout=10):
        """
        Gets current operating mode from the device.
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: device's current operating mode
        :rtype: str
        """
        mode = self._execute_query(self._GET_MODE_CMD, timeout, self._OPERATION_DELAY_TIME)
        return self._remove_embracing_quotation_marks(mode)

    def set_center_frequency(self, frequency, unit, timeout=10):
        """
        Sets given center frequency on the device.
        :param frequency: value from allowed range
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :raises IncorrectOperation: when device is not in appropriate mode, unsupported unit name is provided or
                                    frequency is out of allowed range
        """
        self._check_if_operation_is_allowed(self.set_center_frequency, self._CENTER_FREQUENCY_MODES)
        self._check_frequency_unit(unit)
        self._check_frequency(frequency, unit, self._get_allowed_center_frequency_range())
        command = self._SET_CENTER_FREQUENCY_CMD.format(frequency, unit)
        self._execute_command(command, timeout, self._OPERATION_DELAY_TIME)

    def get_center_frequency(self, unit=FrequencyUnits.Hz, timeout=10):
        """
        Gets current center frequency from the device.
        :param unit: name of unit in which returned frequency should be expressed, i.e. kHz; defaults to Hz
        :type unit: str
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: device's current center frequency
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode or unsupported unit name is provided
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        """
        self._check_if_operation_is_allowed(self.get_center_frequency, self._CENTER_FREQUENCY_MODES)
        self._check_frequency_unit(unit)
        center_frequency = self._execute_query(self._GET_CENTER_FREQUENCY_CMD, timeout, self._OPERATION_DELAY_TIME)
        center_frequency = self._convert_response_to_int(center_frequency)
        return center_frequency / FrequencyUnits.multipliers[unit.lower()]

