    def measure_channel_power(self, timeout=10):
        """
        Starts channel power measurement and gets current channel power measurement from the device.
        :param timeout: time to wait for individual steps of this operation to be finished; defaults to 10 seconds
        :type timeout: int
        :return: device's current channel power measurement
        :rtype: float
        :raises IncorrectOperation: when device is not in appropriate mode
        :raises IncorrectResponse: when device responses with unhandled or incorrect message
        """
        self._check_if_operation_is_allowed(self.measure_channel_power, self._MEASURE_CHANNEL_POWER_MODES)

        self.set_channel_power_measurement(timeout)
        measurement = self._execute_query(self._MEASURE_CHANNEL_POWER_CMD, timeout, self._OPERATION_DELAY_TIME)

        self._check_response(measurement)
        channel_power = measurement.split(',')[0]
        return self._convert_response_to_float(channel_power)

    def _lock_device(self, timeout):
        """
        Locks device if possible before reaching given timeout.
        :param timeout: time to wait for device do became unlocked by other possible user
        :type timeout: int
        :raises DeviceLocked: when device doesn't became unlocked by other user before reaching timeout
        """
        logging.info("Locking device")
        self._check_lock(timeout)
        self._prepare_unlocking_on_crash()
        command = self._LOCK_DEVICE_CMD.format(self._LOCK_FILE_NAME)
        self._transport.execute_command(command, 20)

    def _check_lock(self, timeout):
        """
        Checks whether device became unlocked by other possible user before reaching given timeout.
        :param timeout: time to wait for device do became unlocked by other possible user
        :type timeout: int
        :raises DeviceLocked: when device doesn't became unlocked by other user before reaching timeout
        """
        check_interval = timeout / 10.0
        start_time = datetime.now()

        while self._is_lock_file_present():
            self._check_if_timeout_reached(start_time, timeout)
            sleep(check_interval)

    def _is_lock_file_present(self):
        """
        Checks whether lock file exists in device's memory.
        :return: True if lock file exists, False otherwise
        :rtype: bool
        """
        return self._LOCK_FILE_NAME in self._to_unicode(self._transport.execute_query(self._CHECK_LOCK_CMD, 20))

    @staticmethod
    def _check_if_timeout_reached(start_time, timeout):
        """
        Checks whether given timeout has already been reached.
        :param start_time: timestamp of moment, when time measurement has been started
        :type start_time: datetime
        :param timeout: timeout which will be checked
        :type timeout: int
        :raises DeviceLocked: if timeout has been reached
        """
        if (datetime.now() - start_time).seconds > timeout:
            raise DeviceLocked("Requested signal analyzer is currently used by someone else")

    def _prepare_unlocking_on_crash(self):
        """
        Registers unlocking device to atexit module - this will unlock device when unhandled exception will be raised.
        """
        register(self._unlock_device)

    def _unlock_device(self):
        """
        Unlocks device by removing lock file from device's memory.
        :raises CannotUnlockDevice: when device is still locked after attempt to unlock it
        """
        logging.info("Unlocking device")
        if self._is_lock_file_present():
            command = self._UNLOCK_DEVICE_CMD.format(self._LOCK_FILE_NAME)
            self._transport.execute_command(command, 20)
            sleep(self._DEVICE_LOADING_TIME)
            self._check_if_device_was_unlocked()

    def _check_if_device_was_unlocked(self):
        """
        Checks whether device was successfully unlocked (lock file was removed from device's memory).
        :raises CannotUnlockDevice: when device was not unlocked
        """
        if self._is_lock_file_present():
            raise CannotUnlockDevice("Device is still locked after attempt to unlock it - "
                                     "it must be unlocked manually")

    def _check_if_operation_is_allowed(self, operation, allowed_modes):
        """
        Checks whether given operation can be executed in current operating mode.
        :param operation: operation which will be checked, for logging purposes only
        :type operation: function
        :param allowed_modes: mode names in which operation is allowed
        :type allowed_modes: tuple(str)
        :raises IncorrectOperation: when checked operation is not allowed in current operating mode
        """
        if self._mode not in allowed_modes:
            raise IncorrectOperation("Operation '{}' is not allowed in '{}' mode - set one of {} "
                                     "modes and retry".format(operation.__name__, self._mode, allowed_modes))

    def _check_mode(self, mode):
        """
        Checks if given operating mode comes from available modes list.
        :param mode: name of mode which will be checked
        :type mode: str
        :raises IncorrectOperation: when checked mode does not come from available modes list
        """
        if mode not in self._SUPPORTED_MODES:
            raise IncorrectOperation("Mode '{}' is incorrect".format(mode))

    def _check_frequency_unit(self, unit):
        """
        Checks whether given frequency unit comes from supported frequency units list.
        :param unit: name of unit which will be checked
        :type unit: str
        :raises IncorrectOperation: when checked frequency unit does not come from supported frequency units list
        """
        if not unit or unit.lower() not in self._SUPPORTED_FREQUENCY_UNITS:
            raise IncorrectOperation("Frequency unit '{}' is incorrect".format(unit))

    def _check_frequency(self, frequency, unit, allowed_frequency_range):
        """
        Checks whether given frequency is a number and belongs to allowed frequency range.
        :param frequency: value which will be checked
        :type frequency: float
        :param unit: name of unit in which frequency is provided i.e. kHz
        :type unit: str
        :param allowed_frequency_range: range of frequency values which are allowed, in Hz
        :type allowed_frequency_range: tuple(int, int)
        :raises IncorrectOperation: when checked frequency is not a number or is out of range
        """
        if frequency is None or frequency == '':
            raise IncorrectOperation("Frequency '{}' is incorrect".format(frequency))

        frequency_in_hertz = frequency * FrequencyUnits.multipliers[unit.lower()]

        if frequency_in_hertz < allowed_frequency_range[0] or frequency_in_hertz > allowed_frequency_range[1]:
            frequency = self._remove_scientific_notation(frequency)
            error_msg = "Frequency {} {} is out of range <{} Hz, {} Hz>".format(frequency, unit,
                                                                                *allowed_frequency_range)
            raise IncorrectOperation(error_msg)

    def _get_allowed_center_frequency_range(self):
        """
        Gets allowed center frequency range which is allowed in current operating mode.
        :return: allowed center frequency range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed center frequency is not specified for current mode
        """
        if self._mode in self._SUPPORTED_MODES:
            return -100000000, 9610000000
        else:
            raise InternalError("Allowed center frequency range not specified for '{}' mode".format(self._mode))

    def _get_allowed_frequency_span_range(self):
        """
        Gets frequency span range which is allowed in current operating mode.
        :return: allowed frequency span range
        :rtype: tuple(int, int)
        :raises InternalError: when allowed frequency span is not specified for current mode
        """
        if self._mode == self._SA_MODE:
            return 0, 9000000000
        elif self._mode == self._RTSA_MODE:
            return 280, 10000000
        else:
            raise InternalError("Allowed frequency span range not specified for '{}' mode".format(self._mode))

