    def _check_response(self, response):
        """
        Checks whether given response is not empty.
        :param response: value which will be checked
        :type response: str
        :raises IncorrectResponse: when checked response is empty
        """
        if response is None or response == '':
            raise IncorrectResponse(self._INCORRECT_RESPONSE_RECEIVED_ERROR_MSG.format(response))

    def _convert_response_to_int(self, response):
        """
        Converts response from string to integer.
        :param response: value which will be converted
        :type response: str
        :return: response as integer
        :rtype: int
        :raises IncorrectResponse: when response cannot be converted to integer,
                                   i.e. when string contains non-digit characters
        """
        try:
            return int(float(response))
        except (TypeError, ValueError):
            raise IncorrectResponse(self._INCORRECT_RESPONSE_RECEIVED_ERROR_MSG.format(response))

    def _convert_response_to_float(self, response):
        """
        Converts response from string to floating point number.
        :param response: value which will be converted
        :type response: str
        :return: response as floating point number
        :rtype: float
        :raises IncorrectResponse: when response cannot be converted to floating point number,
                                   i.e. when string contains non-digit characters
        """
        try:
            return float(response)
        except (TypeError, ValueError):
            raise IncorrectResponse(self._INCORRECT_RESPONSE_RECEIVED_ERROR_MSG.format(response))

    @staticmethod
    def _remove_embracing_quotation_marks(mode):
        """
        Strips mode name from embracing quotation marks.
        :param mode: value which will be stripped
        :type mode: str
        :return: mode name without embracing quotation marks
        :rtype: str
        """
        return mode.strip('"')

    @staticmethod
    def _remove_scientific_notation(number):
        """
        Removes scientific notation (i.e. 2.31E+03) from number by expressing it, as string, in standard notation.
        :param number: value from which scientific notation will be removed
        :type number: float
        :return: number as string without scientific notation
        :rtype: str
        """
        return u'{:.12f}'.format(number).rstrip(u'0') if u'e' in str(number).lower() else str(number)
